import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,writeFile,mkdir,rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const label=process.argv[2]||'antes';const out='/tmp/legendgirl-revisao-'+label;
await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/yuna',{recursive:true});
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-yuna-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;document.querySelector('#game-difficulty').value='EASY';const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));for(let i=0;i<200&&!game.state.toyRoomInstance?.instance?.garden?.ready;i++)await new Promise(r=>setTimeout(r,50));window.phase=game.state.toyRoomInstance.instance.garden;if(!phase.ready)throw Error(phase.error||'Jardim indisponível');game.setPaused(true);})()`);

 const report=await evaluate(`(async()=>{
  const {createGardenState,restoreGardenState}=await import('/src/js/garden/GardenSimulation.js');
  const {GARDEN_PLATFORM_BY_ID,gardenSurfaceY}=await import('/src/js/garden/GardenLevel.js');
  const s=createGardenState('EASY'),bee=s.encounters.bees[0],ground=GARDEN_PLATFORM_BY_ID.get(bee.supportId);
  s.stage='RUNNING';s.player.x=bee.homeX-370;s.player.y=gardenSurfaceY(ground,s.player.x);s.player.support=ground.id;s.player.terrain=ground.type;s.safeGround=ground.id;s.trail=[ground.id];phase.state=restoreGardenState(s,'EASY');
  window.revisionFrames=[];let next=0;const wall=performance.now();game.setPaused(false);
  await new Promise(resolve=>{const frame=now=>{const b=phase.state.encounters.bees[0];if(now-wall>=next){phase.render();const f=phase.renderer.frame(phase.state),x=(b.x-f.ox)*f.scale,y=b.y*f.scale+f.oy,c=document.createElement('canvas');c.width=240;c.height=220;const ctx=c.getContext('2d');ctx.fillStyle='#dbe8da';ctx.fillRect(0,0,240,220);ctx.drawImage(phase.canvas,x-65*f.scale,y-95*f.scale,130*f.scale,110*f.scale,0,0,240,203);ctx.fillStyle='#26392b';ctx.font='14px sans-serif';ctx.fillText(b.phase+' '+(now-wall).toFixed(0)+'ms',5,216);revisionFrames.push(c.toDataURL());next+=125;}if(now-wall>1400){game.setPaused(true);resolve();}else requestAnimationFrame(frame);};requestAnimationFrame(frame);});
  return{quadros:revisionFrames.length,tempoAtivo:phase.state.time,etapa:phase.state.stage};
 })()`);console.log(JSON.stringify(report));
 const frames=await evaluate('revisionFrames');for(let i=0;i<frames.length;i++)await writeFile(out+'/abelha-'+i+'.png',Buffer.from(frames[i].split(',')[1],'base64'));
 const sheet=await evaluate(`(()=>{const c=document.createElement('canvas');c.width=960;c.height=660;const ctx=c.getContext('2d');return Promise.all(revisionFrames.slice(0,12).map(async(src,i)=>{const im=new Image();im.src=src;await im.decode();ctx.drawImage(im,i%4*240,Math.floor(i/4)*220);})).then(()=>c.toDataURL());})()`);await writeFile(out+'/abelha-sequencia.png',Buffer.from(sheet.split(',')[1],'base64'));
 const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile(out+'/pagina.png',Buffer.from(shot.result.data,'base64'));
 await writeFile('docs/diario-ia/qa-resultados/yuna/revisao-'+label+'.json',JSON.stringify(report,null,2));
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
